cells={(0,1),(0,2),(0,4),(0,5),(1,0),(1,1),(1,2),(1,3),(1,4),(1,5),(2,1),(2,2),(2,4),(3,2),(3,3),(3,4)}
# square + L orientations missing corners except BR? enumerate exact covers, with exactly one square and 4 L; L orientations all 4 initially
from functools import lru_cache
placements=[]
for r in range(6):
 for c in range(6):
  block={(r+i,c+j) for i in range(2) for j in range(2)}
  if block<=cells: placements.append((block,1,'sq'))
  for miss in [(0,0),(0,1),(1,0),(1,1)]:
   shape={(r+i,c+j) for i in range(2) for j in range(2)}-{(r+miss[0],c+miss[1])}
   if shape<=cells: placements.append((shape,3,miss))
solutions=[]
def go(rem, chosen, sq):
 if not rem:
  if sq==1: solutions.append(chosen[:])
  return
 if len(chosen)>5:return
 p=min(rem)
 for sh,n,k in placements:
  if p in sh and sh<=rem and (k!='sq' or sq==0):
   go(rem-sh,chosen+[(sh,k)],sq+(k=='sq'))
go(cells,[],0)
len(solutions)
